import { defineConfig, type ManifestChunk } from 'vite';

export default defineConfig({
  manifest: {
    customFields(content: string, chunk: ManifestChunk) {
      return {
        hashes: {
          sha384: generateSha384(content),
          sha256: generateSha256(content),
        },
      };
    },
  },
});
```

